  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    weight = batch['weight']\n    adv_diff = ops.sub(ops.tanh(adv_w), ops.tanh(adv_l))\n    cost_effect = ops.relu(cost_gap)\n    loss_raw = ops.sub(cost_effect, adv_diff)\n    weighted_loss = ops.mul(loss_raw, weight)\n    # ensure requires_grad on weighted_loss via adding zero tensor with grad\n    zero = ops.zeros_like(weighted_loss)\n    weighted_loss = weighted_loss + zero\n    return ops.mean(weighted_loss)\n"
